slices.filter:
=and(
  ISBLANK([Số Hoá đơn]),
   COUNT(
    SELECT([Related Chi tiết đơn hàngs][Row ID], [Status] <> "Đã giao hàng")
  ) = 0
    )

menu.showIf:
=COUNT(
  SELECT(
    Nhập đơn hàng[Row ID],
    [Trạng thái thanh toán] <> "đã thanh toán"
  )
) > 0

controls.showIf:
=COUNT(
  SELECT(
    Nhập đơn hàng[Row ID],
    [Trạng thái thanh toán] <> "đã thanh toán"
  )
) > 0

actions.condition:
=IF(
  DAY(TODAY()) < 25,
  TRUE,
  COUNT(
    SELECT(
      KhachHang[MÃ KH],
      AND(
        DATE([Ngày tạo]) = TODAY(),
        [NV phu trach].[Email] = USEREMAIL()
      )
    )
  ) < 8
)

=IF(
  DAY(TODAY()) < 25,
  TRUE,
  COUNT(
    SELECT(
      Giao dịch[Row ID],
      AND(
        DATE([Thời gian tạo]) = TODAY(),
        [Nhân viên phụ trách].[Email] = USEREMAIL()
      )
    )
  ) < 15
)

=COUNT(
  SELECT(
    chấm kpi[Row ID],
    AND(
      [Nv] = [_THISROW].[Nv],
      MONTH([dấu thời gian]) = MONTH(TODAY()),
      YEAR([dấu thời gian]) = YEAR(TODAY())
    )
  )
) = 0

=NOT(
  IN(
    ANY(SELECT(NHANVIEN[Row ID], [Email] = USEREMAIL())),
    SELECT(
      ChiTieuDoanhSo[Nhan Vien],
      AND(
        [Tháng] = MONTH(TODAY()),
        [Năm] = YEAR(TODAY())
      )
    )
  )
)

events.condition:
=AND(
  [Status] = "Đã giao hàng",
  COUNT(
    FILTER(
      "Chi tiết đơn hàng",
      AND(
        [Số HĐ] = [_THISROW].[Số HĐ],
        [Status] <> "Đã giao hàng"
      )
    )
  ) = 0
)
